import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64


PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry gemv_kernel(
    .param .u64 gemv_kernel_param_0,
    .param .u64 gemv_kernel_param_1,
    .param .u64 gemv_kernel_param_2,
    .param .u64 gemv_kernel_param_3,
    .param .u64 gemv_kernel_param_4
)
{
    .reg .pred %p<12>;
    .reg .f32 %f<24>;
    .reg .b32 %r<24>;
    .reg .b64 %rd<40>;

    .shared .align 4 .b8 warpSums[128];

    ld.param.u64 %rd1, [gemv_kernel_param_0];
    ld.param.u64 %rd2, [gemv_kernel_param_1];
    ld.param.u64 %rd3, [gemv_kernel_param_2];
    ld.param.u64 %rd4, [gemv_kernel_param_3];
    ld.param.u64 %rd5, [gemv_kernel_param_4];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    // Persistent-CTA grid-stride loop over output rows to remove
    // wave-quantization tail effect (grid is launched with a block
    // count sized to fill full waves on the GPU; each block then
    // iterates over multiple rows as needed).
    mov.u32 %r1, %ctaid.x;
    cvt.s64.s32 %rd6, %r1;

    mov.u32 %r21, %nctaid.x;
    cvt.s64.s32 %rd30, %r21;

    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %ntid.x;

    // K4 = K / 4  (K assumed non-negative); constant across all rows,
    // hoisted out of the per-row loop.
    shr.s64 %rd10, %rd5, 2;
    shl.b64 %rd16, %rd10, 2;

    cvt.s64.s32 %rd12, %r3;

ROWLOOP:
    setp.ge.s64 %p1, %rd6, %rd4;
    @%p1 bra EXIT;

    // rowPtr = A + row*K (elements) -> bytes
    mul.lo.s64 %rd7, %rd6, %rd5;
    shl.b64 %rd8, %rd7, 2;
    add.s64 %rd9, %rd1, %rd8;

    cvt.s64.s32 %rd11, %r2;

    mov.f32 %f1, 0f00000000;

    setp.ge.s64 %p2, %rd11, %rd10;
    @%p2 bra REM_INIT;

LOOP4:
    shl.b64 %rd13, %rd11, 4;
    add.s64 %rd14, %rd9, %rd13;
    ld.global.v4.f32 {%f2,%f3,%f4,%f5}, [%rd14];
    add.s64 %rd15, %rd2, %rd13;
    ld.global.v4.f32 {%f6,%f7,%f8,%f9}, [%rd15];
    mul.f32 %f10, %f2, %f6;
    fma.rn.f32 %f10, %f3, %f7, %f10;
    fma.rn.f32 %f10, %f4, %f8, %f10;
    fma.rn.f32 %f10, %f5, %f9, %f10;
    add.f32 %f1, %f1, %f10;
    add.s64 %rd11, %rd11, %rd12;
    setp.lt.s64 %p3, %rd11, %rd10;
    @%p3 bra LOOP4;

REM_INIT:
    cvt.s64.s32 %rd17, %r2;
    add.s64 %rd18, %rd16, %rd17;

REM_LOOP:
    setp.ge.s64 %p4, %rd18, %rd5;
    @%p4 bra REDUCE;
    shl.b64 %rd19, %rd18, 2;
    add.s64 %rd20, %rd9, %rd19;
    ld.global.f32 %f11, [%rd20];
    add.s64 %rd21, %rd2, %rd19;
    ld.global.f32 %f12, [%rd21];
    fma.rn.f32 %f1, %f11, %f12, %f1;
    add.s64 %rd18, %rd18, %rd12;
    bra.uni REM_LOOP;

REDUCE:
    mov.u32 %r5, 31;
    mov.u32 %r6, -1;

    mov.b32 %r7, %f1;
    shfl.sync.down.b32 %r8, %r7, 16, %r5, %r6;
    mov.b32 %f13, %r8;
    add.f32 %f1, %f1, %f13;

    mov.b32 %r7, %f1;
    shfl.sync.down.b32 %r8, %r7, 8, %r5, %r6;
    mov.b32 %f13, %r8;
    add.f32 %f1, %f1, %f13;

    mov.b32 %r7, %f1;
    shfl.sync.down.b32 %r8, %r7, 4, %r5, %r6;
    mov.b32 %f13, %r8;
    add.f32 %f1, %f1, %f13;

    mov.b32 %r7, %f1;
    shfl.sync.down.b32 %r8, %r7, 2, %r5, %r6;
    mov.b32 %f13, %r8;
    add.f32 %f1, %f1, %f13;

    mov.b32 %r7, %f1;
    shfl.sync.down.b32 %r8, %r7, 1, %r5, %r6;
    mov.b32 %f13, %r8;
    add.f32 %f1, %f1, %f13;

    and.b32 %r9, %r2, 31;
    shr.u32 %r10, %r2, 5;

    setp.ne.s32 %p5, %r9, 0;
    @%p5 bra SKIP_STORE;

    shl.b32 %r11, %r10, 2;
    mov.u32 %r12, warpSums;
    add.s32 %r13, %r12, %r11;
    st.shared.f32 [%r13], %f1;

SKIP_STORE:
    bar.sync 0;
    setp.ne.s32 %p6, %r10, 0;
    @%p6 bra NEXTROW;

    add.s32 %r14, %r3, 31;
    shr.s32 %r15, %r14, 5;
    setp.ge.s32 %p7, %r9, %r15;
    mov.f32 %f14, 0f00000000;
    @%p7 bra SKIP_LOAD;

    shl.b32 %r16, %r9, 2;
    mov.u32 %r17, warpSums;
    add.s32 %r18, %r17, %r16;
    ld.shared.f32 %f14, [%r18];

SKIP_LOAD:
    mov.b32 %r19, %f14;
    shfl.sync.down.b32 %r20, %r19, 16, %r5, %r6;
    mov.b32 %f15, %r20;
    add.f32 %f14, %f14, %f15;

    mov.b32 %r19, %f14;
    shfl.sync.down.b32 %r20, %r19, 8, %r5, %r6;
    mov.b32 %f15, %r20;
    add.f32 %f14, %f14, %f15;

    mov.b32 %r19, %f14;
    shfl.sync.down.b32 %r20, %r19, 4, %r5, %r6;
    mov.b32 %f15, %r20;
    add.f32 %f14, %f14, %f15;

    mov.b32 %r19, %f14;
    shfl.sync.down.b32 %r20, %r19, 2, %r5, %r6;
    mov.b32 %f15, %r20;
    add.f32 %f14, %f14, %f15;

    mov.b32 %r19, %f14;
    shfl.sync.down.b32 %r20, %r19, 1, %r5, %r6;
    mov.b32 %f15, %r20;
    add.f32 %f14, %f14, %f15;

    setp.ne.s32 %p8, %r9, 0;
    @%p8 bra NEXTROW;

    shl.b64 %rd22, %rd6, 2;
    add.s64 %rd23, %rd3, %rd22;
    st.global.f32 [%rd23], %f14;

NEXTROW:
    // Ensure all reads of warpSums for the current row have completed
    // before the next row's writes overwrite shared memory.
    bar.sync 0;
    add.s64 %rd6, %rd6, %rd30;
    bra.uni ROWLOOP;

EXIT:
    ret;
}
"""

_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    """Look up the compiled entry point to make sure the module is valid."""
    module = _get_module()
    return module.function("gemv_kernel")


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented as a hand-authored
    PTX kernel launched through cutegen.ptx_runtime.PtxModule. Each CUDA
    block performs a vectorized (float4) dot-product reduction over K for
    one or more output rows, using a persistent grid-stride loop over rows
    so that the launch grid is sized to fill full occupancy waves on the
    GPU, eliminating the tail-wave inefficiency of a 1-block-per-row launch.
    """

    def __init__(self):
        super().__init__()
        self._module = None
        self._threads = 256
        # Empirically-derived occupancy limit for this kernel: with 256
        # threads/block and ~34 registers/thread, register pressure
        # (34 * 256 = 8704 regs/block, 65536 regs/SM) allows at most
        # floor(65536 / 8704) = 7 resident blocks per SM.
        self._blocks_per_sm = 7

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "A and B must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, \
            "Expect float32 tensors"
        assert A.dim() == 2, "A must be 2D (M, K)"
        assert B.dim() == 2 and B.size(1) == 1, "B must be (K, 1)"
        assert A.size(1) == B.size(0), "Inner dimensions must match"

        A_c = A.contiguous()
        B_c = B.contiguous()

        M, K = A_c.shape
        C = torch.empty((M, 1), device=A.device, dtype=torch.float32)

        module = self._module if self._module is not None else _get_module()
        self._module = module

        stream = torch.cuda.current_stream()

        threads = self._threads

        try:
            sm_count = torch.cuda.get_device_properties(A.device).multi_processor_count
        except Exception:
            sm_count = 128  # fallback for RTX 4090

        # Size the grid to fill full occupancy waves and avoid a partial
        # tail wave; the kernel internally grid-strides over rows.
        target_blocks = sm_count * self._blocks_per_sm
        grid_blocks = min(int(M), int(target_blocks)) if target_blocks > 0 else int(M)
        grid_blocks = max(grid_blocks, 1)

        grid = (grid_blocks, 1, 1)
        block = (threads, 1, 1)

        module.launch(
            "gemv_kernel",
            grid,
            block,
            [
                u64(A_c.data_ptr()),
                u64(B_c.data_ptr()),
                u64(C.data_ptr()),
                i64(M),
                i64(K),
            ],
            stream=stream,
        )

        return C

