    """
    Matrix-vector multiplication (C = A * B) implemented as a hand-authored
    PTX kernel launched through cutegen.ptx_runtime.PtxModule. Each CUDA
    block now computes ROWS_PER_CTA=4 consecutive output rows, loading each
    B-vector chunk once per iteration and reusing it (via registers) across
    all 4 rows' dot products. This cuts redundant global-memory traffic for
    the B vector by ~4x relative to the one-row-per-CTA scheme and shrinks
    the grid size (fewer, larger CTAs), improving wave utilization on the
    SMs, while keeping the same vectorized float4 accumulation and
    warp-shuffle + shared-memory tree reduction per row.
    """

    def __init__(self):
        super().__init__()
        self._module = None
        self._threads = 256
        self._rows_per_cta = 4

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "A and B must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, \
            "Expect float32 tensors"
        assert A.dim() == 2, "A must be 2D (M, K)"
        assert B.dim() == 2 and B.size(1) == 1, "B must be (K, 1)"
        assert A.size(1) == B.size(0), "Inner dimensions must match"

        A_c = A.contiguous()
        B_c = B.contiguous()

        M, K = A_c.shape
        C = torch.empty((M, 1), device=A.device, dtype=torch.float32)

        module = self._module if self._module is not None else _get_module()
        self._module = module

        stream = torch.cuda.current_stream().cuda_stream

        threads = self._threads
        rows_per_cta = self._rows_per_cta
        num_ctas = (int(M) + rows_per_cta - 1) // rows_per_cta
        grid = (num_ctas, 1, 1)
        block = (threads, 1, 1)

        module.launch(
            "gemv_kernel",
            grid=grid,
            block=block,
            shared_mem_bytes=0,
            stream=stream,
            args=[
                u64(A_c.data_ptr()),
                u64(B_c.data_ptr()),
                u64(C.data_ptr()),
                i64(M),
                i64(K),
            ],
        )

